/**
 * API checks: one test per check in coverage/<feature>/api.json. Checks of a feature run in order,
 * so values saved by one check (e.g. a new booking's id) can be used by the next.
 * Generated by create-qa-suite — change coverage files, not this file.
 */
import { test } from '@playwright/test';
import { runApiCheck } from '../support/api.js';
import { coverage, tags } from '../support/coverage.js';
import type { Value } from '../support/types.js';

for (const feature of coverage.features.filter((f) => f.api.length)) {
  test.describe(`${feature.name} API`, { tag: tags(feature.name, 'api') }, () => {
    test.describe.configure({ mode: 'serial' });
    const ctx = { env: process.env, saved: {} as Record<string, Value> };
    for (const check of feature.api) {
      const declare = check.draft ? test.fixme : test;
      declare(check.title, async ({ request }) => {
        await runApiCheck(request, check, ctx);
      });
    }
  });
}
